232	```javascript
233	// Words whose trailing period does not end a sentence. Compared lower-case and
234	// without any opening bracket or quote. "U.S.A." style initialisms are not
235	// listed: they usually do end a sentence when they come last, and guessing
236	// otherwise would trade one error for another.
237	const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);
238	
239	// A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
240	// only where whitespace or the end of the text follows. Requiring that keeps
241	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
242	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
243	
244	function endsWithAbbreviation(before) {
245	  const last = before.match(/(\S+)$/);
246	  if (last === null) {
247	    return false;
248	  }
249	  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
250	  return ABBREVIATIONS.has(word);
251	}
252	
253	/**
254	 * Count the sentences in a piece of text.
255	 *
256	 * A sentence is a stretch of text containing at least one word and ending at a
257	 * terminator run, or at the end of the text. A lone period after a known
258	 * abbreviation does not end a sentence.
259	 *
260	 * @param {string} text
261	 * @returns {number}
262	 */
263	function sentenceCount(text) {
264	  assertText('sentenceCount', text);
265	  let count = 0;
266	  let start = 0;
267	  for (const match of text.matchAll(TERMINATOR_PATTERN)) {
268	    const before = text.slice(start, match.index);
269	    if (match[1] === '.' && endsWithAbbreviation(before)) {
270	      continue;
271	    }
272	    if (tokenize(before).length > 0) {
273	      count += 1;
274	    }
275	    start = match.index + match[0].length;
276	  }
277	  if (tokenize(text.slice(start)).length > 0) {
278	    count += 1;
279	  }
280	  return count;
281	}
282	
283	module.exports = { wordCount, sentenceCount };
284	```
